<script setup>import MdmShell from '../../components/MdmShell.vue';import StatusPill from '../../components/StatusPill.vue';import {stats,alerts,orders,flow} from '../../api/mock';const trend=[52,58,55,67,63,74,72,81,76,85,89,92];</script>
<template><MdmShell><template #title>主数据总览</template><div class="welcome"><div><h2>主数据运行平稳，3 项风险需要处理</h2><p>统计范围：华东主数据中心 · 数据更新于 13:36</p></div><div><button class="ghost">下载经营日报</button><button class="primary">＋ 新建变更申请</button></div></div><div class="stats"><article v-for="s in stats" :key="s[0]" :class="s[3]"><span>{{s[0]}}</span><strong>{{s[1]}}</strong><small>{{s[2]}}</small><i></i></article></div><div class="flow"><article v-for="(f,i) in flow" :key="f[0]"><small>0{{i+1}}</small><div><span>{{f[0]}}</span><strong>{{f[1]}}</strong><em>{{f[2]}}</em></div><i v-if="i<flow.length-1">→</i></article></div><div class="dash-grid"><section class="panel trend"><div class="panel-head"><div><h3>数据质量趋势</h3><p>近 12 周 · 规则通过率与数据完整度</p></div><div class="legend"><span><i></i>规则通过率</span><span><i></i>数据完整度</span></div></div><div class="chart"><div class="axis"><span>100%</span><span>75%</span><span>50%</span><span>25%</span></div><div class="chart-bars"><div v-for="(v,i) in trend" :key="i"><i :style="{height:v+'%'}"></i><b :style="{bottom:(v*.72)+'%'}"></b><small>W{{i+19}}</small></div></div></div></section><section class="panel alerts"><div class="panel-head"><div><h3>主数据风险</h3><p>按影响范围与紧急程度排序</p></div><a>进入风险中心</a></div><article v-for="a in alerts" :key="a.title"><StatusPill :status="a.level"/><div><b>{{a.title}}</b><p>{{a.detail}}</p><small>{{a.type}} · 负责人 {{a.owner}} · {{a.time}}</small></div></article></section></div><section class="panel focus"><div class="panel-head"><div><h3>重点变更申请</h3><p>交付窗口临近、存在延期或部分到货的订单</p></div><RouterLink to="/admin/purchases">查看全部订单 →</RouterLink></div><table><thead><tr><th>变更单号</th><th>数据域 / 数据对象</th><th>记录数量</th><th>计划发布日期</th><th>治理进度</th><th>完整率</th><th>负责人</th><th>状态</th></tr></thead><tbody><tr v-for="o in orders.slice(0,3)" :key="o.no"><td><b>{{o.no}}</b></td><td><b>{{o.supplier}}</b><small>{{o.material}}</small></td><td>{{o.qty}}</td><td><b>{{o.expected}}</b><small :class="{danger:o.days.includes('逾期')}">{{o.days}}</small></td><td><div class